"""Паспорт исходных условий моделей. --write / --check, только в копии для сборки."""
import argparse
import hashlib
import json
from pathlib import Path
from alchemy_guidance import budget, sales
from rules_data import (HERB, MB, P_SL, CAT_PRICE, CAT_STABLE,
                        proficiency, unstable_fraction, elixir_batch)
from sim_plan import batch_p
from party_kit_report import CARDS, price, materials
from sim_volume import EFF

ROOT=Path(__file__).resolve().parent.parent
DATE='12.11.2026'
SAVE='Источники/Сохранения/alcemy-save-2026-11-09-session17-essences.json'
OUT='Архив/Проверки/Сверка моделей экономики — 2026-11-12.md'
DATA='scripts/economy_audit/current_conditions.json'
MODELS=[
 ('Рынок без указания','sim.py','Уровни I–X; минимальные мастерство и место; бонус — отдельная ось; без классовых ресурсов. Контрольная модель, не текущий Талис.'),
 ('Продажа с конечным пулом','scenario_engine.py','Целый катализатор оплачивается при покупке, остаток переносится; дневной пул и число доз конечны. 30 рабочих дней с реальными отдыхами.'),
 ('Указание: сравнительный сценарий','sim_guidance.py','Чародей 5, мастерство 3, бонус +5; 0 / 7 / 23 расхода. Это условный следующий этап, не текущее мастерство 2.'),
 ('Длинная варка','sim_volume.py','VI–VII: объём 90, VIII: 240; лаборатория как условие будущего сценария; цена и уровень названных эффектов сверены с каталогом.'),
 ('Рост и собственные чернила','sim_player.py','Интеллект +0; полные переходы с нуля. Историческая шкала владения без указания отделена от EXAMPLE_CLASS в личных строках с указанием.'),
 ('Время и исследования','sim_week.py','Мастерство 2, рабочее место +1; только метка: лаборатория +3. Чернила 100/100, метка II 38/45 и обязательный успешный подход с холодной магией; зачёты открытий условного набора учтены до добора практики.'),
 ('Недельный запас','sim_plan.py','Чернила по одному; эликсиры партиями по 6.2; лечение по BATCH_T. Средние часы до годного запаса; будущие оборудование и уровни класса явно заданы.'),
 ('Именные запасы группы','party_kit_report.py','Точный размер последней партии; уровни и цены из каталога, компоненты Каменной кожи и две эссенции Героизма учтены. После M5 оборудование — условное.'),
 ('Таблицы книги экономики','economy_book.py','12 таблиц: продажи, полный рост, ресурсы, исследования, снабжение. Бонус Интеллекта 0, помощника нет; текущий бонус +5.'),
 ('Исторический простой','downtime_day.py','Архивный снимок 01.11.2026, чернила 30/100. Не обновляется до текущего состояния; лабораторная колонка — сравнение, а не доступ для чернил.'),
]


def build():
    state=json.loads((ROOT/SAVE).read_text())['state']
    t=state['talis'];total=t['sp']+t['meta'];slots=sum(int(k)*v for k,v in t['slots'].items())
    b=proficiency(5)+MB[2]+1
    assert b==5 and total==3 and slots==3
    assert CARDS['Щит веры']['lvl']==1 and price(CARDS['Щит веры'])==20
    assert CARDS['Каменная кожа']['lvl']==4
    assert elixir_batch(2,1)==3 and elixir_batch(2,2)==2
    assert elixir_batch(9,1,True)==4 and batch_p(2,2)==2
    assert materials(CARDS['Каменная кожа'])==4*HERB[4]+HERB[4]+CAT_PRICE[4]/CAT_STABLE+100
    for l,(n,p) in EFF.items():
        assert CARDS[n]['lvl']==l and price(CARDS[n])==p,(n,l,p)
    money=state['mat']['gold']
    models=[]
    for title,module,conditions in MODELS:
        path='scripts/'+module
        models.append(dict(model=title,source=path,sha256=hashlib.sha256((ROOT/path).read_bytes()).hexdigest(),conditions=conditions))
    sources=['scripts/elixir_price_audit.py','scripts/cards/price_adjustments.json','scripts/rules.json','scripts/alchemy_guidance.py','scripts/cards/cards_data.py',
             'scripts/report.py','scripts/weekly_economy_report.py','Алхимия Талиса — правила за столом.md',SAVE]
    ink=sales(5,12,40.5,120*.85,0,unstable_fraction(.85),2,item_kind='ink',level=2)
    x=sales(16,P_SL[10],10*HERB[10],3435*.85,CAT_PRICE[10],unstable_fraction(.85),2,item_kind='potion',level=10,class_level=20)
    data=dict(verified=DATE,snapshot=SAVE,current=dict(level=5,mastery=2,bonus=b,workplace=1,root_bonus=7,
              sorcery=total,slot_conversion=slots,maximum_current_spending=total+slots,gold=money),
              rested=dict(pool=7,slots=16,total=budget(5,feat_points=2)),catalyst_stable=CAT_STABLE,
              ink2_profit_per_hour=ink['per_hour'],potion10_profit_per_hour=x['per_hour'],models=models,
              source_hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources})
    lines=['# Сверка моделей экономики',f'\nПроверено {DATE} по действующим правилам и срезу сессии 17. Это паспорт расчётов; игровых операций он не проводит.',
      '\n## Что исправлено',
      '\n- Общий пул после отдыха: **7**, с переводом всех ячеек — **23**, вместо классового сценария 5/21. В текущем снимке — **3**, или максимум **6** с расходом всех оставшихся ячеек; бой и алхимия делят эти ресурсы.',
      '- Катализатор IV порядка не получает бесплатные стабильные применения: **5**, как в §5.2. Ошибочное исключение «10 для X» удалено из продаж.',
      '- Очередь исследований больше не требует заново открыть чернила и этап I метки. Для этапа II помимо объёма обязателен успешный холодный подход; перенос 38/45 с этапа I его не заменяет. В условном наборе зачёты завершённых открытий и этапа метки отделены от производственной практики.',
      '- Партия Щита веры I на M2 — **3**; партия предмета II — **2**. Щит I не растит M2 → M3. В именованных расходниках уровень берётся из каталога, цена 25 зм сохранена.',
      '- Лаборатория +3 доступна сейчас **только метке**. Для остальных работ используется +5 на рабочем месте. Строки VI+ требуют будущего оборудования, а не заявляют нынешний доступ.',
      '\n## Условия каждой модели','\n| Модель | Источник | Проверенные условия |','| --- | --- | --- |']
    lines += [f"| {m['model']} | `{m['source']}` | {m['conditions']} |" for m in models]
    lines += ['\n## Общие условия',
      '\nПродажа обычного предмета — 85% рынка (Гильдии 75% в отдельной колонке), нестабильного — половина **рынка**, не половина сниженной выручки. Фактических продаж модель не создаёт.',
      '\nМатериалы оплачиваются на каждую дозу и попытку. Эссенции и катализатор качеством не экономятся. Рост и лечение выбирают экономию трав на 5+/20; снабжение эликсирами оценивается без этой необязательной экономии и без дополнительных доз от качества, консервативно. Для снабжения доля цены катализатора распределяется по пяти стабильным применениям; для покупки нужен целый катализатор и оборотные деньги. Стоимость катализатора IV — лишь оценка сюжетного ресурса; готовый IV нельзя считать доступной покупкой. Редкие эссенции VII+ в сравнении — 2,5 цены травы, реальная цена требует торга.',
      '\nЧернила I–II — 2 часа на один набор, III–V — 4 часа. Эликсиры I–II — 2 часа на партию, III–V — 4 часа; зелья лечения — 2 часа и собственные партии, VI+ по одной дозе. Длинная варка объёмом относится к эликсирам и чернилам, не к лечению VI+.',
      '\nИсследование формулы: четверть полной основы, эссенция и реактивы за каждую пробу. Катализатор только при завершающей варке. Разбор зелья расходует образец один раз. Переброс не покупает вторую пробу. В прогрессных исследованиях перебрасывается только натуральная 1, в формулах — провал; успешный низкий результат не перебрасывается.',
      '\nОдин переброс на исходную проверку. Таблицы с неограниченным одним перебросом предполагают рабочие блоки до 8 часов и настоящие долгие отдыхи между днями. На текущем M2 за 8 часов максимум 16 доз лечения I, что меньше полного бюджета 23; у старших сценариев запас также проверяется отдельно. Для незавершённого боя или непрерывных дня и рабочей ночи нельзя повторно выдать полный запас в середине работы.',
      '\nБдительный отдых: одна рабочая ночь до 8 часов в неделю, нужна готовая доза и безопасное место; отдых восстанавливает ресурсы после завершения, а не в начале ночи. Помощник отсутствует в основных расчётах; сравнительные ставки помощника не подтверждают найм или расход.',
      '\n## Что остаётся оценкой',
      '\nОбычная продажа — точные вероятности и конечный дневной пул; длинные варки и некоторые исследования — Монте-Карло с фиксированным seed. Полные переходы мастерства в основных сравнительных таблицах — требование / средняя практика: это оценка, без полного округления партий. Именные малые заказы учитывают неполную последнюю партию. Время сверх бюджета показывается дефицитом, а не положительной свободной выручкой.',
      '\nВ доходе 9.9 включён условный вариант повышения до 10.10 на натуральной 20 **с разрешения мастера**; без такого разрешения этот доход нельзя переносить на игру. Само наличие денег не даёт рецепт X или сюжетное сырьё.\n',
      '\nОсечки с неустановленными последствиями, ремонт, аренда, дополнительные реагенты и холодная магия этапа II метки, покупка оборудования и ожидание продавца не оценены числом. Нельзя объявлять их нулевой фактической тратой. Повышения за силу эффекта сохранены; отменена только надбавка за концентрацию (§41).',
      '\n## Контрольные числа',
      f'\nЧернила II: {ink["per_hour"]:.2f} зм/ч при +5 и продаже по 85%; они почти не изменились: даже старый классовый запас покрывал все проверки короткого рабочего дня. Кошелёк снимка — {money:.2f} зм; прибыль не начислена.',
      '\nРеестр исходников и контрольные суммы — `scripts/economy_audit/current_conditions.json`. Полный пересчёт: report.py, weekly_economy_report.py --write, party_kit_report.py --write, economy_book.py --write; проверки — check_all.py --slow --browser.']
    return json.dumps(data,ensure_ascii=False,indent=2)+'\n','\n'.join(lines)+'\n'


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--write',action='store_true');parser.add_argument('--check',action='store_true');args=parser.parse_args()
    data,report=build()
    for name,content in ((DATA,data),(OUT,report)):
        path=ROOT/name
        if args.check:
            if not path.exists() or path.read_text()!=content:raise SystemExit('Паспорт моделей устарел: '+name)
        elif args.write:path.write_text(content)
        else:print(content)
    if args.check:print('PASS: исходные условия десяти моделей, каталог, партии, ресурсы и контрольные суммы')
